from fastapi import FastAPI, Request, Response, Depends, HTTPException
from fastapi.responses import JSONResponse
from starlette.middleware.sessions import SessionMiddleware
import secrets
import time
from typing import Optional
import hashlib

app = FastAPI()
app.add_middleware(SessionMiddleware, secret_key="production-secret-key-2024", session_cookie="session_id")

# In-memory user store (simplified)
users_db = {
    "admin": {"password_hash": hashlib.sha256(b"admin123").hexdigest(), "role": "admin"},
    "user1": {"password_hash": hashlib.sha256(b"password1").hexdigest(), "role": "user"},
}

# Active sessions tracking
active_sessions = {}


def get_client_ip(request: Request) -> str:
    forwarded = request.headers.get("X-Forwarded-For")
    if forwarded:
        return forwarded.split(",")[0].strip()
    return request.client.host


@app.post("/auth/login")
async def login(request: Request):
    body = await request.json()
    username = body.get("username", "")
    password = body.get("password", "")

    password_hash = hashlib.sha256(password.encode()).hexdigest()

    user = users_db.get(username)
    if not user or user["password_hash"] != password_hash:
        raise HTTPException(status_code=401, detail="Invalid credentials")

    # VULNERABILITY: Session is NOT regenerated after authentication
    # The existing session ID (potentially attacker-controlled) persists
    # This allows session fixation attacks
    request.session["authenticated"] = True
    request.session["username"] = username
    request.session["role"] = user["role"]
    request.session["login_time"] = time.time()
    request.session["ip"] = get_client_ip(request)

    active_sessions[request.cookies.get("session_id", "unknown")] = {
        "username": username,
        "login_time": time.time()
    }

    return {"status": "success", "message": f"Welcome {username}"}


@app.get("/auth/session-init")
async def session_init(request: Request):
    """Initialize a session for pre-auth flows (CSRF token, preferences, etc.)"""
    if "initialized" not in request.session:
        request.session["initialized"] = True
        request.session["created_at"] = time.time()
    return {"status": "session_ready"}


@app.get("/api/profile")
async def get_profile(request: Request):
    if not request.session.get("authenticated"):
        raise HTTPException(status_code=403, detail="Not authenticated")
    return {
        "username": request.session["username"],
        "role": request.session["role"],
        "login_time": request.session["login_time"]
    }


@app.post("/api/admin/users")
async def list_users(request: Request):
    if not request.session.get("authenticated"):
        raise HTTPException(status_code=403, detail="Not authenticated")
    if request.session.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Admin required")
    return {"users": list(users_db.keys())}


@app.post("/auth/logout")
async def logout(request: Request):
    session_id = request.cookies.get("session_id")
    if session_id in active_sessions:
        del active_sessions[session_id]
    request.session.clear()
    return {"status": "logged_out"}


@app.get("/health")
async def health():
    return {"status": "healthy", "sessions_active": len(active_sessions)}
